import AppKit

/// 每 0.4 秒看一眼系统剪贴板的 changeCount，有变化就记下来
final class ClipboardMonitor {
    private let pasteboard = NSPasteboard.general
    private let store: ClipboardStore
    private var lastChangeCount: Int
    private var timer: Timer?
    private let imageQueue = DispatchQueue(label: "clipkeeper.image", qos: .utility)

    /// 密码管理器等应用会用这些类型标记"不要记录"
    private let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "com.typeit4me.clipping",
        "de.petermaurer.TransientPasteboardType",
        "Pasteboard generator type",
        "net.antelle.keeweb",
    ]

    /// 系统钥匙串、密码类应用，从它们复制的东西不记录
    private let ignoredBundleIDs: Set<String> = [
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
    ]

    init(store: ClipboardStore) {
        self.store = store
        self.lastChangeCount = pasteboard.changeCount
    }

    func start() {
        let t = Timer(timeInterval: 0.4, repeats: true) { [weak self] _ in
            self?.poll()
        }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    /// 我们自己往剪贴板写东西之后调用，免得把自己的写入再记一遍
    func syncChangeCount() {
        lastChangeCount = pasteboard.changeCount
    }

    private func poll() {
        let count = pasteboard.changeCount
        guard count != lastChangeCount else { return }
        lastChangeCount = count
        guard !AppSettings.shared.paused else { return }
        capture()
    }

    private func capture() {
        let types = Set((pasteboard.types ?? []).map { $0.rawValue })
        if types.isEmpty || !types.isDisjoint(with: ignoredTypes) { return }

        let front = NSWorkspace.shared.frontmostApplication
        let appName = front?.localizedName
        let bundleID = front?.bundleIdentifier
        if let bid = bundleID, ignoredBundleIDs.contains(bid) { return }

        // 1. 文件（在访达里复制文件）
        if let urls = pasteboard.readObjects(forClasses: [NSURL.self],
                                             options: [.urlReadingFileURLsOnly: true]) as? [URL],
           !urls.isEmpty {
            let paths = urls.map { $0.path }
            let hash = Hashing.sha256("files:" + paths.joined(separator: "\n"))
            store.add(ClipItem(kind: .files, filePaths: paths, contentHash: hash,
                               sourceApp: appName, sourceBundleID: bundleID))
            return
        }

        // 2. 文本（同时带文本和图片的，比如表格单元格，优先存文本）
        if var str = pasteboard.string(forType: .string),
           !str.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            if str.utf16.count > 500_000 { str = String(str.prefix(500_000)) }
            let hash = Hashing.sha256("text:" + str)
            store.add(ClipItem(kind: .text, text: str, contentHash: hash,
                               sourceApp: appName, sourceBundleID: bundleID))
            return
        }

        // 3. 图片（截图、从浏览器复制图片等）
        let pngType = NSPasteboard.PasteboardType.png
        let tiffType = NSPasteboard.PasteboardType.tiff
        let imageType: NSPasteboard.PasteboardType?
        if types.contains(pngType.rawValue) {
            imageType = pngType
        } else if types.contains(tiffType.rawValue) {
            imageType = tiffType
        } else {
            imageType = nil
        }
        guard let type = imageType,
              let data = pasteboard.data(forType: type),
              data.count <= 40_000_000 else { return }

        let hash = Hashing.sha256(data)
        if store.bumpExisting(hash: hash, sourceApp: appName, bundleID: bundleID) { return }

        let dir = store.imagesURL
        let isPNG = (type == pngType)
        imageQueue.async { [weak self] in
            guard let saved = ImageUtil.savePNG(data: data, alreadyPNG: isPNG, to: dir) else { return }
            DispatchQueue.main.async {
                self?.store.add(ClipItem(kind: .image, imageFile: saved.name,
                                         imageWidth: saved.width, imageHeight: saved.height,
                                         contentHash: hash, sourceApp: appName, sourceBundleID: bundleID))
            }
        }
    }
}
